<template>
  <section class="reports-page">
    <div class="reports-hero"><h2>Reportes y documentos</h2><p>Genere nuevamente documentos históricos y reportes del almacén.</p></div>
    <div class="report-grid">
      <article class="report-card"><div class="report-title">Notas de ingreso</div><p>Busque por N.º de nota o documento de remisión. Puede descargar PDF o Excel.</p><input v-model="busIngreso" @input="cargarIngresos" class="form-control" placeholder="Ej.: N.º 000001 o remisión"><div class="results"> <div v-for="i in ingresos" :key="i.id" class="result-row"><div><strong>{{i.numero_nota}}</strong><span>{{i.proveedor || 'Sin proveedor'}} · {{i.fecha}}<template v-if="i.numero_remision"> · Remisión: {{i.numero_remision}}</template></span></div><div><button class="btn-orange" @click="descargar('api/ingresos/'+i.id+'/pdf')">PDF</button><button class="btn-outline" @click="descargar('api/reportes/ingresos/'+i.id+'/excel')">Excel</button></div></div><div v-if="busIngreso && !ingresos.length" class="empty">Sin coincidencias.</div></div></article>
      <article class="report-card"><div class="report-title">Notas de salida</div><p>Busque por número de salida o pedido. Puede descargar PDF o Excel.</p><input v-model="busSalida" @input="cargarSalidas" class="form-control" placeholder="Ej.: 12 o N.º pedido"><div class="results"><div v-for="s in salidas" :key="s.id" class="result-row"><div><strong>Salida N.º {{s.numero_salida}}</strong><span>{{s.destino || 'Sin destino'}} · {{s.fecha}}<template v-if="s.numero_pedido"> · Pedido: {{s.numero_pedido}}</template></span></div><div><button class="btn-orange" @click="descargar('api/reportes/salidas/'+s.id+'/pdf')">PDF</button><button class="btn-outline" @click="descargar('api/reportes/salidas/'+s.id+'/excel')">Excel</button></div></div></div></article>
      <article class="report-card report-wide"><div class="report-title">Reporte de inventario</div><p>Busque y agregue uno o varios productos para generar un reporte específico, o genere el inventario completo.</p>
<div class="filter-row"><div class="search-wrap"><input v-model="inv.buscar" @input="buscarInventarioProductos" class="form-control" placeholder="Buscar producto / LINAME para agregar"><div v-if="invSugerencias.length" class="suggestions"><button v-for="p in invSugerencias" :key="p.id" @click="seleccionarInventarioProducto(p)"><strong>{{p.codigo}}</strong> — {{p.nombre}}</button></div></div></div>
<div v-if="productosInventario.length" class="inventory-selection"><div class="inventory-head"><strong>Productos seleccionados para el reporte</strong><span>{{productosInventario.length}} producto(s)</span></div><div class="inventory-table-wrap"><table class="inventory-table"><thead><tr><th>LINAME / Código</th><th>Producto</th><th>Partida</th><th>Acciones</th></tr></thead><tbody><tr v-for="(p,index) in productosInventario" :key="p.id"><td>{{p.codigo}}</td><td v-if="editandoInventario!==index">{{p.nombre}}</td><td v-else><input v-model="edicionInventario.nombre" class="table-input"></td><td>{{p.partida_presupuestaria?.codigo || p.partida || '—'}}</td><td class="table-actions"><button class="edit-btn" @click="editarInventario(index)">{{editandoInventario===index?'Guardar':'Editar'}}</button><button class="delete-btn" @click="eliminarInventario(index)">Eliminar</button></td></tr></tbody></table></div></div>
<div class="actions" v-if="productosInventario.length"><button class="btn-orange" @click="generarSeleccionados('pdf')">Generar PDF seleccionados</button><button class="btn-outline" @click="generarSeleccionados('excel')">Generar EXCEL seleccionados</button></div>
<div class="complete-actions"><strong>Inventario completo</strong><span>Incluye todos los productos registrados en el inventario al momento de generar el reporte.</span><div class="actions"><button class="btn-orange" @click="descargar('api/reportes/inventario/pdf')">Generar inventario completo PDF</button><button class="btn-outline" @click="descargar('api/reportes/inventario/excel')">Generar inventario completo EXCEL</button></div></div></article>
      <article class="report-card report-wide"><div class="report-title">Kardex por producto</div><p>Seleccione un producto y, opcionalmente, un rango de fechas.</p><div class="filter-row"><div class="search-wrap"><input v-model="textoProducto" @input="buscarProductos" class="form-control" placeholder="Buscar por LINAME o nombre"><div v-if="sugerencias.length" class="suggestions"><button v-for="p in sugerencias" :key="p.id" @click="seleccionarProducto(p)"><strong>{{p.codigo}}</strong> — {{p.nombre}}</button></div></div><input v-model="desde" type="date" class="form-control"><input v-model="hasta" type="date" class="form-control"></div><div class="selected" v-if="producto">{{producto.codigo}} — {{producto.nombre}}</div><div class="actions"><button class="btn-orange" :disabled="!producto" @click="descargar('api/reportes/kardex/pdf',{producto_id:producto?.id,desde,hasta})">Generar Kardex PDF</button></div></article>
    </div>
  </section>
</template>
<script setup>
import axios from 'axios'; import {reactive,ref,onMounted} from 'vue';
const ingresos=ref([]),salidas=ref([]),busIngreso=ref(''),busSalida=ref(''),textoProducto=ref(''),sugerencias=ref([]),producto=ref(null),desde=ref(''),hasta=ref(''),invSugerencias=ref([]); const inv=reactive({buscar:''}),productosInventario=ref([]),editandoInventario=ref(null),edicionInventario=reactive({nombre:''}); let ti,ts,tp,tinv;
const cargarIngresos=()=>{clearTimeout(ti);ti=setTimeout(async()=>{ingresos.value=(await axios.get('api/reportes/ingresos',{params:{buscar:busIngreso.value}})).data},250)};
const cargarSalidas=()=>{clearTimeout(ts);ts=setTimeout(async()=>{salidas.value=(await axios.get('api/reportes/salidas',{params:{buscar:busSalida.value}})).data},250)};
const buscarProductos=()=>{clearTimeout(tp);tp=setTimeout(async()=>{if(textoProducto.value.trim().length<1){sugerencias.value=[];return}sugerencias.value=(await axios.get('api/medicamentos',{params:{buscar:textoProducto.value}})).data.slice(0,8)},200)};
const seleccionarProducto=p=>{producto.value=p;textoProducto.value=`${p.codigo} — ${p.nombre}`;sugerencias.value=[]};
const buscarInventarioProductos=()=>{clearTimeout(tinv);tinv=setTimeout(async()=>{if(inv.buscar.trim().length<1){invSugerencias.value=[];return}const data=(await axios.get('api/medicamentos',{params:{buscar:inv.buscar}})).data;invSugerencias.value=(Array.isArray(data)?data:(data.data||[])).slice(0,8)},200)};
const seleccionarInventarioProducto=p=>{if(!productosInventario.value.some(x=>x.id===p.id))productosInventario.value.push({...p});inv.buscar='';invSugerencias.value=[]};
const eliminarInventario=index=>{if(editandoInventario.value===index)editandoInventario.value=null;productosInventario.value.splice(index,1)};
const editarInventario=index=>{if(editandoInventario.value===index){productosInventario.value[index].nombre=edicionInventario.nombre;editandoInventario.value=null;return}editandoInventario.value=index;edicionInventario.nombre=productosInventario.value[index].nombre};
const generarSeleccionados=formato=>{const ids=productosInventario.value.map(p=>p.id).join(',');descargar('api/reportes/inventario/'+formato,{producto_ids:ids})};
const descargar=async(url,params={})=>{const r=await axios.get(url,{params,responseType:'blob'});const type=r.headers['content-type']||'application/octet-stream';const blob=new Blob([r.data],{type});const cd=r.headers['content-disposition']||'';const match=/filename[^;=\n]*=((['"]).*?\2|[^;\n]*)/.exec(cd);let filename=match&&match[1]?match[1].replace(/['"]/g,''):'reporte';if(!/\.(pdf|xls|xlsx)$/i.test(filename)){filename+=type.includes('pdf')?'.pdf':'.xls'}const a=document.createElement('a');const objectUrl=URL.createObjectURL(blob);a.href=objectUrl;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(objectUrl),1000)};
onMounted(()=>{cargarIngresos();cargarSalidas()});
</script>
<style scoped>
