ry-table th{background:#f4f7fa;color:#0b3d62}.inventory-table th,.inventory-table td{padding:10px;border-bottom:1px solid #e3e9ee;text-align:left}.table-actions{white-space:nowrap}.edit-btn,.delete-btn{border:0;border-radius:6px;padding:6px 9px;margin-right:6px}.edit-btn{background:#0b3d62;color:#fff}.delete-btn{background:#e85d04;color:#fff}.table-input{width:100%;padding:6px;border:1px solid #cdd8e2;border-radius:5px}.complete-actions{margin-top:20px;border-top:2px solid #e85d04;padding-top:14px}.complete-actions strong{display:block;color:#0b3d62;font-size:1.05rem}.complete-actions span{display:block;color:#667788;margin:4px 0}@media(max-width:850px){.report-grid{grid-template-columns:1fr}.filter-row{grid-template-columns:1fr}.report-wide{grid-column:auto}}
</style>
